            self::q('environnement', 'Couper le moteur lors d’un arrêt prolongé peut être pertinent si :', ['Cela peut se faire sans gêner ni compromettre la sécurité', 'Je suis engagé dans un carrefour', 'Je roule sur autoroute'], [0], 'La décision dépend de la situation de circulation et des dispositifs du véhicule. Cette question nécessite une validation éditoriale avant publication.', 'medium', $safety, true),
            self::q('environnement', 'Le covoiturage peut contribuer à :', ['Réduire le nombre de véhicules utilisés pour des trajets comparables', 'Supprimer la nécessité de respecter le code de la route', 'Éviter l’usage de la ceinture'], [0], 'Partager un trajet peut réduire les émissions par personne, tout en conservant toutes les règles de sécurité.', 'easy', $safety, true),
        ];

        foreach ($questions as $index => &$question) {
            $question['public_id'] = 'CDR-SEED-'.str_pad((string) ($index + 1), 4, '0', STR_PAD_LEFT);
        }

        return $questions;
    }

    private static function q(
        string $category,
        string $question,
        array $options,
        array $correctIndexes,
        string $explanation,
        string $difficulty,
        string $reference,
        bool $requiresReview = false,
        ?string $mediaPath = null,
    ): array {
        return [
            'category_code' => $category,
            'question_text' => $question,
            'difficulty' => $difficulty,
            'answer_type' => count($correctIndexes) > 1 ? 'multiple' : 'single',
            'explanation' => $explanation,
            'official_reference' => $reference,
            'status' => $requiresReview ? 'draft' : 'published',
            'requires_review' => $requiresReview,
            'media_type' => $mediaPath ? 'image' : null,
            'media_path' => $mediaPath,
            'options' => array_map(fn (string $label, int $index) => [
                'label' => $label,
                'is_correct' => in_array($index, $correctIndexes, true),
            ], $options, array_keys($options)),
        ];
    }
}
